import sas.*; // Import der SaS-Bibliothek
import sasio.*;
import java.awt.Color; // Import der Klasse Color, um einfacher auf die Farben zuzugreifen.

class Autorennen
{
    // Deklarationen
   View fenster; 
   Auto auto1;
   Rennstrecke strecke;
   Rectangle auto;
   int rundenzahl;
   boolean rundeZaehlen;
   Text rundenAnzeige;
    // Konstruktor dieser Klasse
   Autorennen()
   {
        // Initialisierungen
      fenster = new View(800, 650, "SaS-Programm");
      fenster.setBackgroundColor(Color.GREEN);
      strecke = new Rennstrecke();
      auto1 = new Auto();
      rundenzahl = 3;
      rundenAnzeige = new Text(600, 20, "Runden 3");
      rundeZaehlen = false;
      auto1.zumStart(440, 110, 114);
   }

   public void highScore(String dateiname) {
      String[] eintraege = StringFileTools.loadFileInStringArray(dateiname);
      String zeitstring = eintraege[0].substring(eintraege[0].indexOf("#") + 1, eintraege[0].length());
      double zeit = timeToDouble(zeitstring);
      String minName = eintraege[0].substring(0, eintraege[0].indexOf("#"));
      double minZeit = zeit;
      int minIndex = 0;
      for (int i = 1; i < eintraege.length; i++) {
         zeitstring = eintraege[i].substring(eintraege[i].indexOf("#") + 1, eintraege[i].length());
         zeit = timeToDouble(zeitstring);
         if (zeit < minZeit) {
            minZeit = zeit;
            minIndex = i;
            minName = eintraege[i].substring(0, eintraege[i].indexOf("#"));
         }
      }
      Tools.message(minName + " " + minZeit, "Bestzeit");
   }

   public double timeToDouble(String time) {
      String sekunden = time.substring(0, time.indexOf(","));
      String zehntel = time.substring(time.indexOf(",") + 1, time.length());
      return Tools.stringToDouble(sekunden + "." + zehntel);
   }

   public void speichern(String dateiname, String datensatz) {
      if (!StringFileTools.fileExists(dateiname)) {
         StringFileTools.writeInFile(dateiname, datensatz);
      } else {
         StringFileTools.appendToFile(dateiname, datensatz);
      }
   }
   void spielstarten()
   {
      String name = Tools.inputDialog("Geben Sie Ihren Namen an");
      long zeit = Tools.getStartTime();
      while (!fenster.keyBackspacePressed() && rundenzahl > 0)
      {

         if (fenster.keyRightPressed())
         {
            auto1.lenkeRechts();

         }

         if (fenster.keyLeftPressed())
         {
            auto1.lenkeLinks();

         }

         if (fenster.keyUpPressed())
         {
            if (strecke.aufStrecke(auto1)) {
               auto1.fahre(5);
            }
         }

         if (fenster.keyDownPressed())
         {
            auto1.fahre(-5);
         }

         if (strecke.rundeGefahren(auto1)) {
            rundenzahl = rundenzahl - 1;
            rundenAnzeige.setText("Runden " + rundenzahl);
         }
         fenster.wait(20);
      }
      String gefahreneZeit = Tools.getElapsedTimeString(zeit);
      new Text(500, 550, "Gefahrene Zeit: " + gefahreneZeit + " Sekunden");
      speichern("highscoreAutorennen.txt", name + "#" + gefahreneZeit);
      highScore("highscoreAutorennen.txt");
   }

   public static void main(String[] args) {
      Autorennen ar = new Autorennen();
      ar.spielstarten();
   }
}

import sas.*;
public class Rennstrecke
{

    Picture strecke;
    Picture strecke2;
    Picture strecke3;
    Picture strecke4;
    Polygon ziellinie;
    boolean rundeZaehlen;

    public Rennstrecke()
    {  
        strecke = new Picture(80,0,"rennstrecke.png");
        ziellinie = new Polygon(530,92);
        ziellinie.add(2,2);
        ziellinie.add(-42,98);
        ziellinie.add(-44,96);   

        rundeZaehlen = false;
    }

    public boolean aufStrecke(Auto pAuto) {
        return strecke.intersects(pAuto.gibBild()) /*|| strecke2.intersects(pAuto.gibBild()) || 
        strecke3.intersects(pAuto.gibBild()) || strecke4.intersects(pAuto.gibBild())*/;
    }

    public boolean rundeGefahren(Auto pAuto) {
        boolean rg = false;
        if (pAuto.gibBild().getShapeY()>300) {
            rundeZaehlen = true;
        }
        if (pAuto.gibBild().intersects(ziellinie) && rundeZaehlen) {
            rg = true;
            rundeZaehlen = false;
        }
        return rg;
    }
}

import sas.*; // Import der SaS-Bibliothek
import java.awt.Color; // Import der Klasse Color, um einfacher auf die Farben zuzugreifen.

class Auto
{

    Picture auto;

    Auto()
    {
        auto = new Picture(0,0,50, 25, "autorot.png");
    }

    public void zumStart(int pX, int pY, double pWinkel) {
       auto.moveTo(pX,pY);
       auto.turnTo(pWinkel);
    }

    public void fahre(int strecke) {
       auto.move(strecke);
    }

    public void lenkeRechts() {

        auto.turn(5);
    }

    public void lenkeLinks(){

        auto.turn(-5);
    }

    public Picture gibBild() {
        return auto;
    }

}
